settings.customCss:
/* MegaForm Gen-3 split-photo shell. Scope: .mfp.mfp-terracotta-product-feedback */
.mfp.mfp-terracotta-product-feedback{
  --tc-bg:#1e110a;
  --tc-card:var(--mf-page-surface,var(--mf-preset-surface,#fdf8f3));
  --tc-ink:var(--mf-page-text,var(--mf-preset-text,#241507));
  --tc-heading:var(--mf-page-heading,var(--mf-preset-text,#241507));
  --tc-muted:var(--mf-page-muted,color-mix(in srgb,var(--tc-ink) 58%,transparent));
  --tc-line:var(--mf-page-border,var(--mf-preset-border,#ecddd0));
  --tc-input:var(--mf-page-input-bg,var(--mf-preset-surface,#ffffff));
  --tc-primary:var(--mf-page-primary,var(--mf-preset-primary,#c45c2a));
  --tc-primary-hover:color-mix(in srgb,var(--tc-primary) 82%,#000000);
  --tc-soft:color-mix(in srgb,var(--tc-primary) 10%,var(--tc-card));
  --tc-on-primary:var(--mf-preset-on-primary,#ffffff);
  --tc-error:#c0392b;
  --tc-font:var(--mf-page-font-family,Inter,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif);
  --tc-display:Georgia,"Times New Roman",serif;
  width:100%;
  max-width:1152px;
  margin:0 auto;
  color:var(--tc-ink);
  font-family:var(--tc-font);
}
.mfp.mfp-terracotta-product-feedback,.mfp.mfp-terracotta-product-feedback *,.mfp.mfp-terracotta-product-feedback *::before,.mfp.mfp-terracotta-product-feedback *::after{box-sizing:border-box}
.mfp-terracotta-product-feedback .mfp-stage{width:100%;padding:32px;border-radius:24px;background:var(--tc-bg)}
.mfp-terracotta-product-feedback .mfp-card{
  display:grid;
  grid-template-columns:minmax(280px,5fr) minmax(430px,7fr);
  width:min(100%,896px);
  min-height:650px;
  margin:0 auto;
  overflow:hidden;
  border:1px solid color-mix(in srgb,var(--tc-line) 62%,transparent);
  border-radius:24px;
  background:var(--tc-card);
  box-shadow:0 32px 80px rgba(0,0,0,.48);
}
.mfp-terracotta-product-feedback .mfp-hero{position:relative;min-height:100%;overflow:hidden;color:#ffffff}
.mfp-terracotta-product-feedback .mfp-hero-image{
  position:absolute;
  inset:0;
  background-image:url('/Modules/MegaForm/img/terracotta-product-feedback/hero.jpg');
  background-position:center;
  background-size:cover;
}
.DnnModule .mfp-terracotta-product-feedback .mfp-hero-image{background-image:url('/DesktopModules/MegaForm/Assets/img/terracotta-product-feedback/hero.jpg')}
.mfp-terracotta-product-feedback .mfp-hero-overlay{
  position:absolute;
  inset:0;
  background:linear-gradient(160deg,rgba(10,10,10,.68) 0%,rgba(10,10,10,.20) 54%,color-mix(in srgb,var(--tc-primary) 18%,transparent) 100%);
}
.mfp-terracotta-product-feedback .mfp-brand{position:absolute;z-index:2;top:32px;left:32px;display:flex;align-items:center;gap:10px}
.mfp-terracotta-product-feedback .mfp-brand-mark{
  display:grid;
  place-items:center;
  width:32px;
  height:32px;
  border-radius:8px;
  background:var(--tc-primary);
  color:#ffffff;
  font-size:14px;
  font-weight:800;
}
.mfp-terracotta-product-feedback .mfp-brand-name{color:#ffffff;font-size:13px;font-weight:800;letter-spacing:.16em}
.mfp-terracotta-product-feedback .mfp-hero-copy{position:absolute;z-index:2;right:0;bottom:0;left:0;padding:40px}
.mfp-terracotta-product-feedback .mfp-hero-title{
  max-width:13ch;
  margin:0;
  color:#ffffff;
  font-family:var(--tc-display);
  font-size:clamp(26px,3vw,34px);
  font-weight:700;
  line-height:1.22;
}
.mfp-terracotta-product-feedback .mfp-hero-sub{margin:14px 0 0;color:rgba(255,255,255,.72);font-size:14px;line-height:1.55}
.mfp-terracotta-product-feedback .mfp-hero-rule{width:40px;height:2px;margin-top:20px;border-radius:999px;background:var(--tc-primary)}
.mfp-terracotta-product-feedback .mfp-form-pane{display:flex;min-width:0;flex-direction:column;justify-content:center;padding:44px 48px;background:var(--tc-card)}
.mfp-terracotta-product-feedback .mfp-back-label{display:inline-flex;align-items:center;gap:7px;margin:0 0 28px;color:var(--tc-muted);font-size:12px;font-weight:600}
.mfp-terracotta-product-feedback .mfp-eyebrow{margin:0 0 7px;color:var(--tc-primary);font-size:10px;font-weight:800;letter-spacing:.34em;text-transform:uppercase}
.mfp-terracotta-product-feedback .mfp-form-title{margin:0;color:var(--tc-heading);font-family:var(--tc-display);font-size:clamp(32px,4vw,42px);font-weight:700;line-height:1.08}
.mfp-terracotta-product-feedback .mfp-form-subtitle{max-width:46ch;margin:10px 0 28px;color:var(--tc-muted);font-size:14px;line-height:1.6}
.mfp-terracotta-product-feedback .mfp-stack{display:grid;gap:16px}
.mfp-terracotta-product-feedback .mfp-field-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.mfp-terracotta-product-feedback .mf-field-group{min-width:0;margin:0}
.mfp-terracotta-product-feedback .mf-field-label{display:block;margin:0 0 7px;color:var(--tc-heading);font-size:12px;font-weight:800;letter-spacing:.035em;text-transform:uppercase}
.mfp-terracotta-product-feedback .mf-required{color:var(--tc-error)}
.mfp-terracotta-product-feedback .mf-input,.mfp-terracotta-product-feedback .mf-select,.mfp-terracotta-product-feedback .mf-textarea,
.mfp-terracotta-product-feedback input:not([type='checkbox']):not([type='radio']),.mfp-terracotta-product-feedback select,.mfp-terracotta-product-feedback textarea{
  width:100%!important;
  min-height:46px!important;
  padding:11px 15px!important;
  border:1px solid var(--tc-line)!important;
  border-radius:12px!important;
  outline:0!important;
  background:var(--tc-input)!important;
  color:var(--tc-ink)!important;
  box-shadow:none!important;
  font:inherit!important;
  font-size:14px!important;
  transition:border-color .16s ease,box-shadow .16s ease!important;
}
.mfp-terracotta-product-feedback .mf-textarea,.mfp-terracotta-product-feedback textarea{min-height:106px!important;resize:vertical!important}
.mfp-terracotta-product-feedback .mf-input:focus,.mfp-terracotta-product-feedback .mf-select:focus,.mfp-terracotta-product-feedback .mf-textarea:focus,
.mfp-terracotta-product-feedback input:focus,.mfp-terracotta-product-feedback select:focus,.mfp-terracotta-product-feedback textarea:focus{
  border-color:var(--tc-primary)!important;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--tc-primary) 16%,transparent)!important;
}
.mfp-terracotta-product-feedback input::placeholder,.mfp-terracotta-product-feedback textarea::placeholder{color:color-mix(in srgb,var(--tc-muted) 56%,transparent)}
.mfp-terracotta-product-feedback .mf-field-help,.mfp-terracotta-product-feedback .mf-field-error{margin-top:5px;font-size:12px;line-height:1.4}
.mfp-terracotta-product-feedback .mf-field-error{color:var(--tc-error)}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-group{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-item{display:inline-flex!important;width:auto!important;margin:0!important;padding:0!important}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-control{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;clip-path:inset(50%)!important}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-ui{
  display:inline-flex!important;
  align-items:center!important;
  min-height:32px!important;
  padding:7px 13px!important;
  border:1px solid var(--tc-line)!important;
  border-radius:999px!important;
  background:var(--tc-input)!important;
  color:var(--tc-muted)!important;
  box-shadow:none!important;
  transition:all .16s ease!important;
}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-label{color:inherit!important;font-size:12px!important;font-weight:600!important}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-control:checked + .mf-option-ui{border-color:var(--tc-primary)!important;background:var(--tc-soft)!important;color:var(--tc-primary)!important}
.mfp-terracotta-product-feedback .mfp-chip-field .mf-option-control:focus-visible + .mf-option-ui{outline:2px solid var(--tc-primary)!important;outline-offset:2px!important}
.mfp-terracotta-product-feedback .mfp-check-field .mf-option-group{display:block!important}
.mfp-terracotta-product-feedback .mfp-check-field .mf-option-item{display:flex!important;align-items:flex-start!important;gap:10px!important;margin:0!important;padding:0!important}
.mfp-terracotta-product-feedback .mfp-check-field .mf-option-control{position:static!important;width:17px!important;height:17px!important;margin:3px 0 0!important;accent-color:var(--tc-primary)!important;opacity:1!important}
.mfp-terracotta-product-feedback .mfp-check-field .mf-option-ui{display:block!important;padding:0!important;border:0!important;background:transparent!important;color:var(--tc-muted)!important}
.mfp-terracotta-product-feedback .mfp-check-field .mf-option-label{color:inherit!important;font-size:14px!important;line-height:1.55!important}
.mfp-terracotta-product-feedback .mfp-actions{display:flex;align-items:center;gap:12px;margin-top:22px}
.mfp-terracotta-product-feedback .mfp-btn{
  display:inline-flex;
  min-height:48px;
  align-items:center;
  justify-content:center;
  gap:10px;
  border:1px solid transparent;
  border-radius:12px;
  padding:12px 22px;
  font:inherit;
  font-size:14px;
  font-weight:800;
  text-decoration:none;
  cursor:pointer;
  transition:transform .12s ease,background .16s ease,border-color .16s ease,opacity .16s ease;
}
.mfp-terracotta-product-feedback .mfp-btn:hover{transform:translateY(-1px)}
.mfp-terracotta-product-feedback .mfp-btn-primary{flex:1;background:var(--tc-ink);color:var(--tc-on-primary)}
.mfp-terracotta-product-feedback .mfp-btn-primary:hover{background:color-mix(in srgb,var(--tc-ink) 86%,var(--tc-primary))}
.mfp-terracotta-product-feedback .mfp-btn-secondary{border-color:var(--tc-line);background:transparent;color:var(--tc-muted)}
.mfp-terracotta-product-feedback .mfp-divider{display:flex;align-items:center;gap:12px;margin:18px 0;color:var(--tc-muted);font-size:12px}
.mfp-terracotta-product-feedback .mfp-divider::before,.mfp-terracotta-product-feedback .mfp-divider::after{content:"";height:1px;flex:1;background:var(--tc-line)}
.mfp-terracotta-product-feedback .mfp-provider-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.mfp-terracotta-product-feedback .mfp-provider{border-color:var(--tc-line);background:transparent;color:var(--tc-ink)}
.mfp-terracotta-product-feedback .mfp-provider:hover{border-color:var(--tc-primary);color:var(--tc-primary)}
.mfp-terracotta-product-feedback .mfp-footnote{margin:24px 0 0;text-align:center;color:var(--tc-muted);font-size:14px}
.mfp-terracotta-product-feedback .mfp-footnote a{color:var(--tc-primary);font-weight:800;text-decoration:none}
.mfp-terracotta-product-feedback .mfp-hidden-fields{display:none!important}
.mfp-terracotta-product-feedback .mf-form-title,.mfp-terracotta-product-feedback .mf-form-description,.mfp-terracotta-product-feedback .mf-success-message,.mfp-terracotta-product-feedback .mf-form-actions{display:none!important}
.mf-form-wrapper:has(.mfp-terracotta-product-feedback)>.mf-form-inner{width:100%!important;max-width:1152px!important}
.mf-form-wrapper:has(.mfp-terracotta-product-feedback) .mf-form-actions{display:none!important}
@media(max-width:760px){
  .mfp-terracotta-product-feedback .mfp-stage{padding:14px}
  .mfp-terracotta-product-feedback .mfp-card{grid-template-columns:1fr;min-height:0;border-radius:20px}
  .mfp-terracotta-product-feedback .mfp-hero{min-height:190px}
  .mfp-terracotta-product-feedback .mfp-brand{top:20px;left:20px}
  .mfp-terracotta-product-feedback .mfp-hero-copy{display:none}
  .mfp-terracotta-product-feedback .mfp-form-pane{padding:28px 24px 32px}
  .mfp-terracotta-product-feedback .mfp-back-label{margin-bottom:22px}
}
@media(max-width:520px){
  .mfp-terracotta-product-feedback .mfp-stage{padding:0;border-radius:20px}
  .mfp-terracotta-product-feedback .mfp-field-row,.mfp-terracotta-product-feedback .mfp-provider-row{grid-template-columns:1fr}
  .mfp-terracotta-product-feedback .mfp-form-pane{padding:26px 20px 30px}
  .mfp-terracotta-product-feedback .mfp-form-title{font-size:32px}
  .mfp-terracotta-product-feedback .mfp-actions{align-items:stretch;flex-direction:column-reverse}
  .mfp-terracotta-product-feedback .mfp-btn{width:100%}
}

.mfp-terracotta-product-feedback .mf-rating{display:flex;align-items:center;gap:12px}
.mfp-terracotta-product-feedback .mf-rating-items{display:flex;gap:3px}
.mfp-terracotta-product-feedback .mf-rating-item,.mfp-terracotta-product-feedback .mf-star{padding:0;border:0;background:transparent;color:var(--tc-line);font-size:30px;line-height:1;cursor:pointer}
.mfp-terracotta-product-feedback .mf-rating-item.is-active,.mfp-terracotta-product-feedback .mf-star.is-active{color:var(--tc-primary)}
.mfp-terracotta-product-feedback .mf-rating-on{color:var(--tc-primary)}
.mfp-terracotta-product-feedback .mf-rating-value{color:var(--tc-muted);font-size:13px;font-weight:700}
.mfp-terracotta-product-feedback .mfp-char-hint{margin:-7px 0 0;text-align:right;color:var(--tc-muted);font-size:11px}
